function act(obs, mem) {
  var DT = 0.05, RAD = 57.2957795;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) { a = a % 360; if (a > 180) a -= 360; if (a < -180) a += 360; return a; }
  function nn(v, d) { return (typeof v === "number" && isFinite(v)) ? v : d; }

  /* ---------------- persistent state ---------------- */
  if (!mem.init) {
    mem.init = 1;
    mem.x = nn(obs.x, 20); mem.y = nn(obs.y, 20);
    mem.vx = 0; mem.vy = 0;
    mem.bias = 0;
    mem.head = nn(obs.heading, 0);
    mem.turnRate = 0;
    mem.hQ = [];
    mem.spF = nn(obs.speed, 0);
    mem.baseI = 0;
    mem.mode = 0;                 /* 0 goto, 1 slide along obstacle, 2 recover */
    mem.modeT = nn(obs.t, 0);
    mem.tPrev = nn(obs.t, 0);
    mem.side = 1;                 /* +1 : obstacle kept on left, -1 : on right */
    mem.recSide = 1;
    mem.bestD = 1e9;
    mem.bestT = nn(obs.t, 0);
    mem.lastMoveT = nn(obs.t, 0);
    mem.prevIdx = nn(obs.targetIndex, 0);
    mem.prevR = [10, 10, 10, 10, 10];
    mem.vMax = 1.9;
    mem.turnSign = 1;
    mem.dirAcc = 0;
    mem.slideCount = 0;
    mem.slideEntryD = 1e9;
    mem.prevDPath = 10;
  }

  var t = nn(obs.t, mem.tPrev + DT);
  mem.tPrev = t;

  /* ---------------- motion estimate ---------------- */
  var x = nn(obs.x, mem.x), y = nn(obs.y, mem.y);
  mem.vx += 0.18 * ((x - mem.x) / DT - mem.vx);
  mem.vy += 0.18 * ((y - mem.y) / DT - mem.vy);
  mem.x = x; mem.y = y;
  var spGps = Math.sqrt(mem.vx * mem.vx + mem.vy * mem.vy);

  var compass = nn(obs.heading, mem.head);
  var head = wrap(compass + mem.bias);
  mem.hQ.push(head);
  if (mem.hQ.length > 5) mem.hQ.shift();
  var tr = wrap(head - mem.hQ[0]) / (DT * Math.max(1, mem.hQ.length - 1));
  mem.turnRate += 0.35 * (tr - mem.turnRate);

  /* compass bias + sideslip: reconcile compass with actual track */
  if (spGps > 0.75 && Math.abs(mem.turnRate) < 25) {
    mem.bias += clamp(wrap(Math.atan2(mem.vy, mem.vx) * RAD - head), -1.5, 1.5) * 0.02;
    mem.bias = clamp(mem.bias, -35, 35);
    head = wrap(compass + mem.bias);
  }

  mem.spF += 0.4 * (nn(obs.speed, spGps) - mem.spF);
  if (mem.spF > 0.25 || Math.abs(mem.turnRate) > 15) mem.lastMoveT = t;

  /* ---------------- range sensors ---------------- */
  var rays = [], r = [], i, q;
  for (i = 0; i < 5; i++) {
    q = nn(obs.rays ? obs.rays[i] : 10, 10);
    rays.push(clamp(q, 0.05, 10));
    r.push(Math.min(rays[i], mem.prevR[i]));   /* conservative: 1-tick min filter */
  }
  mem.prevR = rays;

  var dFront = r[2];
  var dPath = Math.min(r[2], 1.3 * r[1], 1.3 * r[3]);
  var openL = r[3] + r[4], openR = r[0] + r[1];

  /* ---------------- target ---------------- */
  var tx = nn(obs.targetX, nn(obs.goalX, 20));
  var ty = nn(obs.targetY, nn(obs.goalY, 20));
  var ddx = tx - x, ddy = ty - y;
  var dist = Math.sqrt(ddx * ddx + ddy * ddy);
  var err = wrap(Math.atan2(ddy, ddx) * RAD - head);

  var idx = nn(obs.targetIndex, mem.prevIdx);
  if (idx !== mem.prevIdx) {
    mem.prevIdx = idx;
    mem.bestD = 1e9; mem.bestT = t;
    mem.mode = 0; mem.slideCount = 0; mem.slideEntryD = 1e9; mem.baseI = 0;
  }
  if (dist < mem.bestD - 0.25 || dist < 1.05) { mem.bestD = dist; mem.bestT = t; }

  /* ---------------- potential field ---------------- */
  var px = 1.35 * Math.cos(err / RAD), py = 1.35 * Math.sin(err / RAD);
  var ANG = [-60, -30, 0, 30, 60], RO = 7;
  for (i = 0; i < 5; i++) {
    if (r[i] >= RO) continue;
    var w = (RO - r[i]) / RO, ww = 1.2 * w + 2.2 * w * w;
    if (i === 2) {
      py += ((openL >= openR) ? 1 : -1) * ww * 1.6;   /* split head-on push to open side */
    } else {
      var a = ANG[i] / RAD;
      px -= ww * Math.cos(a);
      py -= ww * Math.sin(a);
    }
  }
  var desRel = Math.atan2(py, px) * RAD;

  /* ---------------- behaviour selection ---------------- */
  var noProgress = t - mem.bestT, noMove = t - mem.lastMoveT;

  if (mem.mode !== 2 && (noMove > 2.0 ||
      (noProgress > 5.0 && Math.abs(mem.spF) < 0.35 && Math.abs(mem.turnRate) < 12))) {
    mem.mode = 2; mem.modeT = t;
    mem.recSide = (Math.abs(openL - openR) > 0.4) ? ((openL > openR) ? 1 : -1)
                                                  : ((py >= 0) ? 1 : -1);
  }
  if (mem.mode === 0 && dist > 2.5 && dFront < 3.6 && noProgress > 2.0) {
    mem.mode = 1; mem.modeT = t; mem.slideEntryD = dist; mem.slideCount = 0;
    mem.side = (py >= 0) ? -1 : 1;
  }
  if (mem.mode === 0 && dist > 3 && noProgress > 7.0) {
    mem.mode = 1; mem.modeT = t; mem.slideEntryD = dist; mem.slideCount = 0;
    mem.side = (desRel >= 0) ? -1 : 1;
  }
  if (mem.mode === 1) {
    if (dist < 1.8 || (dFront > 4.5 && Math.abs(err) < 45 && dist < mem.slideEntryD - 1.0)) {
      mem.mode = 0; mem.bestT = t; mem.bestD = dist;
    } else if (t - mem.modeT > 8.0) {
      mem.slideCount++;
      if (mem.slideCount > 1) { mem.mode = 2; mem.modeT = t; mem.recSide = -mem.side; }
      else { mem.side = -mem.side; mem.modeT = t; }
    }
  }
  if (mem.mode === 2 && t - mem.modeT > 2.2) {
    mem.mode = 0; mem.bestT = t; mem.bestD = dist;
  }

  /* ---------------- control ---------------- */
  var baseCmd = 0, steerCmd = 0, vDes;

  if (mem.mode === 2) {
    var rt = t - mem.modeT;
    if (rt < 0.55) { baseCmd = -0.45; steerCmd = -0.30 * mem.recSide; }      /* back out   */
    else if (rt < 1.5) { baseCmd = 0.05; steerCmd = 0.95 * mem.recSide; }     /* turn around */
    else { baseCmd = 0.50; steerCmd = 0.30 * mem.recSide; }                   /* set off     */
    mem.baseI = 0;
  } else {
    if (mem.mode === 1) {
      var dSide = (mem.side > 0) ? r[3] : r[1];
      var dSideF = (mem.side > 0) ? r[4] : r[0];
      var dSF = Math.min(dSide, 1.15 * dSideF);
      if (dFront < 2.0) steerCmd = -0.9 * mem.side;                          /* corner: turn away */
      else steerCmd = mem.side * clamp(0.5 * (dSF - 1.35), -0.55, 0.65);     /* hold wall distance */
      vDes = (dFront < 1.6) ? 0.55 : ((dFront < 2.8) ? 0.9 : 1.15);
    } else {
      steerCmd = clamp(0.9 * desRel / 55 - mem.turnRate / 150, -1, 1);
      vDes = mem.vMax * clamp(1 - Math.abs(err) / 115, 0.08, 1);
      if (Math.abs(err) > 140) vDes = 0;
      if (dist < 9) vDes = Math.min(vDes, 0.55 + 0.2 * dist);
    }
    vDes = Math.min(vDes, 1.25 * Math.sqrt(Math.max(0, dPath - 1.15)));
    var vErr = vDes - mem.spF;
    mem.baseI = clamp(mem.baseI + 1.7 * vErr * DT, -0.55, 1);
    baseCmd = clamp(mem.baseI + 0.4 * vErr, -1, 1);
    if (Math.abs(baseCmd) > 0.04 && Math.abs(baseCmd) < 0.22 && Math.abs(mem.spF) < 0.22) {
      baseCmd = baseCmd > 0 ? 0.3 : -0.3;                                    /* break deadband */
    }
  }

  /* ---------------- speed ceiling ---------------- */
  if (dPath < 0.75) mem.vMax = Math.max(1.2, mem.vMax * 0.9);
  else if (Math.min(r[0], r[1], r[2], r[3], r[4]) > 7.5) mem.vMax = Math.min(2.4, mem.vMax + 0.008);

  /* ---------------- motor mapping self-calibration ---------------- */
  if (Math.abs(steerCmd) > 0.35 && Math.abs(mem.turnRate) > 8) {
    mem.dirAcc = clamp(mem.dirAcc + steerCmd * mem.turnRate * DT, -300, 300);
  }
  mem.dirAcc *= 0.998;
  if (mem.dirAcc < -80) { mem.turnSign = -mem.turnSign; mem.dirAcc = 0; }

  var s = mem.turnSign * steerCmd;
  return { left: clamp(baseCmd - s, -1, 1), right: clamp(baseCmd + s, -1, 1) };
}

function act(obs, mem) {
  var RAD = 57.2957795;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) { return ((a % 360) + 540) % 360 - 180; }

  if (!mem.init) {
    mem.init = 1;
    mem.px = obs.x; mem.py = obs.y;
    mem.h = isFinite(obs.heading) ? obs.heading : 0;
    mem.lastD = 1e9;
    mem.stuckT = obs.t;
    mem.recDir = 1;
    return { left: 0.3, right: 0.3 };
  }

  // Heading estimation: smoothed compass + speed-scaled GPS velocity
  var dx = obs.x - mem.px;
  var dy = obs.y - mem.py;
  var mv = Math.sqrt(dx * dx + dy * dy);
  mem.px = obs.x; mem.py = obs.y;

  mem.h += wrap(obs.heading - mem.h) * 0.10;
  if (mv > 0.01) {
    mem.h += wrap(Math.atan2(dy, dx) * RAD - mem.h) * clamp(mv * 5, 0, 0.35);
  }
  mem.h = wrap(mem.h);

  // Sanitize rays
  var rays = [];
  for (var i = 0; i < 5; i++) {
    var r = (isFinite(obs.rays[i]) && obs.rays[i] >= 0) ? Math.min(obs.rays[i], 10) : 10;
    rays.push(r);
  }
  var minR = Math.min(rays[0], rays[1], rays[2], rays[3], rays[4]);

  // Target direction
  var tx = obs.targetX - obs.x;
  var ty = obs.targetY - obs.y;
  var dist = Math.sqrt(tx * tx + ty * ty);
  var dLen = Math.max(0.01, dist);

  // World-frame desired direction (target + arena boundary)
  var desX = tx / dLen, desY = ty / dLen;
  var m = 3, bw = 1.0, f;
  if (obs.x < m) { f = (m - obs.x) / m; desX += bw * f * f; }
  if (obs.x > 40 - m) { f = (obs.x - (40 - m)) / m; desX -= bw * f * f; }
  if (obs.y < m) { f = (m - obs.y) / m; desY += bw * f * f; }
  if (obs.y > 40 - m) { f = (obs.y - (40 - m)) / m; desY -= bw * f * f; }

  var err = wrap(Math.atan2(desY, desX) * RAD - mem.h);

  // Body-frame obstacle bias
  if (rays[2] < 3) {
    var openL = rays[3] + rays[4];
    var openR = rays[0] + rays[1];
    err += (openL > openR ? 1 : -1) * (3 - rays[2]) / 3 * 50;
  }
  if (rays[0] < 1.5) err += (1.5 - rays[0]) * 15;
  if (rays[1] < 2) err += (2 - rays[1]) * 10;
  if (rays[3] < 1.5) err -= (1.5 - rays[3]) * 15;
  if (rays[4] < 2) err -= (2 - rays[4]) * 10;

  err = wrap(err);

  // Stuck detection
  if (dist < mem.lastD - 0.08) {
    mem.stuckT = obs.t;
    mem.lastD = dist;
  }

  // Recovery maneuver
  if (obs.t - mem.stuckT > 6) {
    var rt = obs.t - mem.stuckT - 6;
    if (rt < 0.5) return { left: -0.35, right: -0.35 };
    if (rt < 1.5) return { left: mem.recDir * 0.45, right: -mem.recDir * 0.45 };
    if (rt < 2.2) return { left: 0.4, right: 0.4 };
    mem.stuckT = obs.t;
    mem.lastD = dist;
    mem.recDir = -mem.recDir;
  }

  // Emergency avoidance
  if (minR < 0.6) {
    var oL = rays[3] + rays[4];
    var oR = rays[0] + rays[1];
    return oL > oR ? { left: 0.35, right: -0.35 } : { left: -0.35, right: 0.35 };
  }

  // Speed control
  var speed = 0.65 * Math.max(0.12, 1 - Math.abs(err) / 180);
  if (minR < 3) speed = Math.min(speed, 0.5);
  if (minR < 1.5) speed = Math.min(speed, 0.28);
  if (dist < 1.5) speed = Math.min(speed, 0.3);
  if (dist < 1.1) speed = Math.min(speed, 0.18);

  // Steering
  var steer = clamp(err * 0.012, -0.35, 0.35);
  var left = speed - steer;
  var right = speed + steer;

  if (Math.abs(left) < 0.12 && Math.abs(right) < 0.12) {
    left = 0.15; right = 0.15;
  }

  return {
    left: clamp(left, -1, 1),
    right: clamp(right, -1, 1)
  };
}

function act(obs, mem) {
  var RAD = 57.2957795;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function wrap(a) { a = a % 360; if (a > 180) a -= 360; if (a < -180) a += 360; return a; }
  function nn(v, d) { return (typeof v === "number" && isFinite(v)) ? v : d; }

  if (!mem.init) {
    mem.init = 1;
    mem.px = nn(obs.x, 20); mem.py = nn(obs.y, 20);
    mem.h = nn(obs.heading, 0);
    mem.vx = 0; mem.vy = 0;
    mem.gSpd = 0; mem.slip = 0;
    mem.tPrev = nn(obs.t, 0);
    mem.mode = 0; mem.modeT = 0; mem.recDir = 1; mem.recCount = 0;
    mem.prevIdx = nn(obs.targetIndex, 0);
    mem.steer = 0;
    mem.bestD = 1e9; mem.bestT = nn(obs.t, 0);
    mem.pHist = [];
    mem.stuckT = nn(obs.t, 0);
    return { left: 0.3, right: 0.3 };
  }

  var t = nn(obs.t, mem.tPrev + 0.05);
  var dt = clamp(t - mem.tPrev, 0.02, 0.15);
  mem.tPrev = t;

  // GPS velocity estimation with jump rejection
  var x = nn(obs.x, mem.px), y = nn(obs.y, mem.py);
  var dx = x - mem.px, dy = y - mem.py;
  var mv = Math.sqrt(dx * dx + dy * dy);
  if (mv < 0.5) {
    mem.vx += 0.3 * (dx / dt - mem.vx);
    mem.vy += 0.3 * (dy / dt - mem.vy);
  } else { mem.vx *= 0.5; mem.vy *= 0.5; }
  mem.gSpd = Math.sqrt(mem.vx * mem.vx + mem.vy * mem.vy);
  mem.px = x; mem.py = y;

  mem.pHist.push([x, y, t]);
  while (mem.pHist.length > 0 && t - mem.pHist[0][2] > 3) mem.pHist.shift();

  // Slip detection
  var ws = Math.abs(nn(obs.speed, 0));
  if (ws > 0.3 && mem.gSpd > 0.05) {
    mem.slip += 0.05 * (clamp(1 - mem.gSpd / ws, 0, 1) - mem.slip);
  } else mem.slip *= 0.97;

  // Heading: smoothed compass + GPS bias correction when going straight
  var comp = nn(obs.heading, mem.h);
  mem.h = wrap(mem.h + 0.1 * wrap(comp - mem.h));
  if (mem.gSpd > 0.2 && mv < 0.5 && Math.abs(mem.steer) < 0.06) {
    var gh = Math.atan2(mem.vy, mem.vx) * RAD;
    mem.h = wrap(mem.h + 0.05 * wrap(gh - mem.h));
  }
  var h = mem.h;

  // Target + arena boundary avoidance
  var tx = nn(obs.targetX, nn(obs.goalX, 20));
  var ty = nn(obs.targetY, nn(obs.goalY, 20));
  var ddx = tx - x, ddy = ty - y;
  var dist = Math.sqrt(ddx * ddx + ddy * ddy);
  var desX = ddx / Math.max(0.01, dist), desY = ddy / Math.max(0.01, dist);
  var m = 3, bw = 2;
  if (x < m) desX += bw * (m - x) / m;
  if (x > 40 - m) desX -= bw * (x - (40 - m)) / m;
  if (y < m) desY += bw * (m - y) / m;
  if (y > 40 - m) desY -= bw * (y - (40 - m)) / m;
  var dn = Math.sqrt(desX * desX + desY * desY);
  if (dn > 0.01) { desX /= dn; desY /= dn; }
  var err = wrap(Math.atan2(desY, desX) * RAD - h);

  // Progress tracking
  var idx = nn(obs.targetIndex, 0);
  if (idx !== mem.prevIdx) {
    mem.prevIdx = idx;
    mem.bestD = 1e9; mem.bestT = t;
    mem.mode = 0; mem.stuckT = t; mem.recCount = 0;
  }
  if (dist < mem.bestD - 0.15) { mem.bestD = dist; mem.bestT = t; }

  // Stuck detection: position-based OR no-progress
  var moved = false;
  for (var i = 0; i < mem.pHist.length; i++) {
    var pdx = x - mem.pHist[i][0], pdy = y - mem.pHist[i][1];
    if (pdx * pdx + pdy * pdy > 0.1) { moved = true; break; }
  }
  if (moved) {
    mem.stuckT = t;
    if (mem.mode === 1 && t - mem.modeT > 3.5) mem.mode = 0;
  }
  var np = t - mem.bestT;
  if (mem.mode !== 1 && ((!moved && t - mem.stuckT > 2.0) || np > 15)) {
    mem.mode = 1; mem.modeT = t; mem.recCount++;
    var ol = 0, or_ = 0;
    for (var i = 0; i < 5; i++) {
      var rv = nn(obs.rays && obs.rays[i], 10);
      if (i >= 3) ol += rv; else or_ += rv;
    }
    mem.recDir = ol > or_ ? 1 : -1;
    if (mem.recCount % 3 === 0) mem.recDir = -mem.recDir;
  }

  // Aggressive recovery: hard backup → turn to open → push forward
  if (mem.mode === 1) {
    var rt = t - mem.modeT, cl, cr;
    if (rt < 1.5) { cl = cr = -0.85; }
    else if (rt < 2.5) { cl = -0.7 * mem.recDir; cr = 0.7 * mem.recDir; }
    else if (rt < 4.0) { cl = cr = 0.55; }
    else { mem.mode = 0; mem.stuckT = t; cl = cr = 0.3; }
    return { left: clamp(cl, -1, 1), right: clamp(cr, -1, 1) };
  }

  // Range sensors
  var rays = [], minR = 10;
  for (var i = 0; i < 5; i++) {
    var r = clamp(nn(obs.rays && obs.rays[i], 10), 0.05, 10);
    rays.push(r);
    if (r < minR) minR = r;
  }

  // Body-frame obstacle avoidance
  var os = 0;
  if (rays[2] < 5) {
    var ol2 = rays[3] + rays[4], or2 = rays[0] + rays[1];
    os += (ol2 > or2 ? 1 : -1) * (5 - rays[2]) / 5 * 0.15;
  }
  if (rays[1] < 2.5) os += (2.5 - rays[1]) * 0.05;
  if (rays[3] < 2.5) os -= (2.5 - rays[3]) * 0.05;
  if (rays[0] < 1.8) os += (1.8 - rays[0]) * 0.06;
  if (rays[4] < 1.8) os -= (1.8 - rays[4]) * 0.06;

  // Rate-limited steering: low-gain heading + immediate obstacle bias
  var hs = clamp(err * 0.003, -0.15, 0.15);
  var steerTarget = clamp(hs + os, -0.35, 0.35);
  mem.steer += clamp(steerTarget - mem.steer, -0.015, 0.015);

  // Speed management
  var speed = 0.7;
  speed *= clamp(1 - Math.abs(err) / 150, 0.25, 1);
  if (minR < 2.5) speed = Math.min(speed, 0.4);
  if (minR < 1.2) speed = Math.min(speed, 0.2);
  if (dist < 2) speed = Math.min(speed, 0.3 + 0.2 * dist);
  if (dist < 1.2) speed = Math.min(speed, 0.18);
  if (dist < 0.8) speed = Math.min(speed, 0.1);
  if (mem.slip > 0.3) speed *= clamp(1 - (mem.slip - 0.3) * 1.5, 0.3, 1);

  var left = speed - mem.steer;
  var right = speed + mem.steer;
  if (Math.abs(left) < 0.08 && Math.abs(right) < 0.08) { left = 0.12; right = 0.12; }

  return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };
}

