  if (targetIndex !== mem.lastTargetIndex) {
    mem.lastTargetIndex = targetIndex;
    mem.path = [];
    mem.lastPlan = -999;
    mem.bestDist = 1e9;
    mem.lastProgress = now;
    mem.stuck = 0;
    mem.recoverEnd = -999;
    mem.trim = (Number(mem.trim) || 0) * 0.5;
