    mem.emEnd = now + 1.15;
    mem.emSide = emSide;
    mem.lastEm = now;
    mem.lastEmSide = emSide;
    mem.emCooldown = now + 1.35;
    mem.emExtended = false;
    mem.path = [];
    mem.lastPlan = -999;
    mem.stuck = 0;
