      mem.recoverStart = now;
      mem.recoverEnd = now + 1.3;
      mem.recoverSide = rside;
      mem.lastRecover = now;
      mem.lastRecoverSide = rside;
      mem.stuck = 0;
      mem.lastProgress = now;
      mem.path = [];
      mem.lastPlan = -999;
