        }

        var step = (ddx2 !== 0 && ddy2 !== 0) ? 1.41421356 : 1.0;
        var cg = mem.grid[ni];

        if (cg >= 0) step += 0.035;
        else step -= 0.012;
        if (cg > 0) step += cg * 0.008;

        var tentative = gScore[cur] + step;

        if (tentative < gScore[ni] - 1e-9) {
