      var c = bestG;
      var guard = 0;

      while (c >= 0 && guard++ < 20000) {
        path.push(c);
        if (c === start) break;
        c = came[c];
        if (c === -1) break;
      }

      if (path.length > 0 && path[path.length - 1] === start) {
        path.reverse();
