    if (absE > 110) fwd = Math.min(fwd, 0.18);
    if (Math.abs(turn) > 0.82) fwd *= 0.68;

    var safe = 0.42 + Math.max(0, speed) * 0.62;
    if (frontC < safe) {
      var ratio = clamp((frontC - 0.28) / Math.max(0.15, safe - 0.28), 0.02, 1);
      fwd = Math.min(fwd, ratio * 0.95);
    }
    if (frontC < 0.92) fwd = Math.min(fwd, 0.30);
    if (frontC < 0.64) fwd = Math.min(fwd, 0.03);
    if (frontC < 0.42) fwd = Math.min(fwd, -0.06);
    if (frontMin < 0.40) fwd = Math.min(fwd, 0.34);
    if (leftClear < 0.38 || rightClear < 0.38) fwd = Math.min(fwd, 0.55);
    if (Math.min(r[0], r[4]) < 0.30) fwd = Math.min(fwd, 0.36);
    if (dist < 1.15) fwd = Math.min(fwd, 0.72);
