    mem.lastTargetIndex = targetIndex;
    mem.txLast = tx;
    mem.tyLast = ty;
    mem.path = [];
    mem.lastPlan = -999;
    mem.bestDist = 1e9;
    mem.lastProgress = now;
    mem.stuck = 0;
    mem.escUntil = -999;
    mem.recUntil = -999;
    mem.turnF = 0;
    mem.refH = trueH;
    mem.noPathSince = -999;
