    mem.refH = wrap(mem.refH + clamp(dref, -mstep, mstep));

    var errBase = wrap(mem.refH - trueH);
    var avoid = 0;

    if (leftC < 1.05) avoid -= (1.05 - leftC) * 42;
    if (rightC < 1.05) avoid += (1.05 - rightC) * 42;

