    }

    if (frontNear < 0.90) fwd = Math.min(fwd, 0.42);
    if (frontNear < 0.70) fwd = Math.min(fwd, 0.24);
    if (sideMin < 0.52) fwd = Math.min(fwd, 0.55);
    if (sideMin < 0.34) fwd = Math.min(fwd, 0.30);
    if (mem.path && mem.path.length === 0 && dist > 1.5 &&
