  right = dead(right);

  // Estimate compass bias only while moving mostly straight in clear space.
  var old = null;
  var bestAge = 1e9;
  for (var hi = 0; hi < mem.hist.length; hi++) {
    var age = now - mem.hist[hi].t;
    if (age >= 0.45 && age <= 1.0) {
