  var dxT = tx - px;
  var dyT = ty - py;
  var dist = Math.sqrt(dxT * dxT + dyT * dyT);
  if (!isFinite(dist)) dist = 1e9;
  if (dist < (Number(mem.bestDist) || 1e9) - 0.06) {
