  var targetBearing = Math.atan2(dyT, dxT) * DEG;
  if (!isFinite(targetBearing)) targetBearing = 0;
  var directErr = wrap(targetBearing - trueH);

  var frontC = Math.min(mem.rMed[2], raw[2]);
  var frontNear = Math.min(mem.rMed[1], mem.rMed[2], mem.rMed[3]);
  var frontSafe = Math.min(raw[1], raw[2], raw[3]);
  var leftC = Math.min(mem.rMed[3], mem.rMed[4]);
  var rightC = Math.min(mem.rMed[1], mem.rMed[0]);
  var leftSafe = Math.min(raw[3], raw[4]);
  var rightSafe = Math.min(raw[1], raw[0]);
  var sideMin = Math.min(leftSafe, rightSafe);
  var farMin = Math.min(raw[0], raw[4]);
  var nearAngleMin = Math.min(raw[1], raw[3]);

