        cy = (i - cx) / GW;

        var x0 = cx - infR;
        var x1 = cx + infR;
        var y0 = cy - infR;
        var y1 = cy + infR;
        if (x0 < 0) x0 = 0;
        if (x1 >= GW) x1 = GW - 1;
        if (y0 < 0) y0 = 0;
        if (y1 >= GH) y1 = GH - 1;

        for (y = y0; y <= y1; y++) {
          row = y * GW;
          for (x = x0; x <= x1; x++) {
            var ddx = x - cx;
            var ddy = y - cy;
