    }

    var ix0 = Math.round(mem.fx / RES);
    var iy0 = Math.round(mem.fy / RES);
    ix0 = clamp(ix0, 0, GW - 1);
    iy0 = clamp(iy0, 0, GH - 1);

    for (var sy = -2; sy <= 2; sy++) {
      for (var sx = -2; sx <= 2; sx++) {
        var sxx = ix0 + sx;
        var syy = iy0 + sy;
