    var ixg = Math.round(tx / RES);
    var iyg = Math.round(ty / RES);
    ixg = clamp(ixg, 0, GW - 1);
    iyg = clamp(iyg, 0, GH - 1);

    var bestG = -1;
    var bestGD = 1e18;

    for (var rr = 0; rr <= 22; rr++) {
      var gx0 = ixg - rr;
      var gx1 = ixg + rr;
      var gy0 = iyg - rr;
      var gy1 = iyg + rr;
      if (gx0 < 0) gx0 = 0;
      if (gx1 >= GW) gx1 = GW - 1;
      if (gy0 < 0) gy0 = 0;
      if (gy1 >= GH) gy1 = GH - 1;

      for (var gy = gy0; gy <= gy1; gy++) {
        for (var gx = gx0; gx <= gx1; gx++) {
          if (Math.max(Math.abs(gx - ixg), Math.abs(gy - iyg)) !== rr) continue;
          var gid = gy * GW + gx;
          if (!blocked[gid]) {
            var gdx = gx - ixg;
            var gdy = gy - iyg;
            var gd2 = gdx * gdx + gdy * gdy;
            if (gd2 < bestGD) {
              bestGD = gd2;
              bestG = gid;
            }
