      if (bestG >= 0) break;
    }

    if (bestG < 0) return [];

    var start = iy0 * GW + ix0;
    if (start === bestG) return [start];

    var gScore = new Float32Array(N);
    var came = new Int32Array(N);
    var closed = new Uint8Array(N);
    for (i = 0; i < N; i++) {
      gScore[i] = 1e9;
      came[i] = -1;
    }

    var gx2 = bestG % GW;
    var gy2 = (bestG - gx2) / GW;

    function heur(ix, iy) {
      var ax = Math.abs(ix - gx2);
      var ay = Math.abs(iy - gy2);
      var mn = ax < ay ? ax : ay;
      var mx = ax > ay ? ax : ay;
