    return [];
  }

  var activeEsc = now < (Number(mem.escUntil) || -999);
  var activeRec = now < (Number(mem.recUntil) || -999);

  if (!activeEsc && !activeRec) {
    var movingForward = speed > 0.10 || (Number(mem.prevCmdAvg) || 0) > 0.10;
    var imminent =
      (frontSafe < 0.44) ||
      (frontSafe < 0.66 && movingForward) ||
      (frontSafe < 0.78 && speed > 0.45) ||
      (farMin < 0.48 && frontSafe < 1.10 && movingForward) ||
      (nearAngleMin < 0.33 && frontSafe < 0.95 && movingForward) ||
      (frontNear < 0.72 && speed > 0.50);

    if (imminent && now > (Number(mem.escCooldown) || -999)) {
