      mem.recStart = now;
      mem.recUntil = now + 1.15;
      mem.recSide = rs;
      mem.lastRec = now;
      mem.lastRecSide = rs;
      mem.stuck = 0;
      mem.lastProgress = now;
      mem.path = [];
      mem.lastPlan = -999;
