    if (Math.abs(dref) > 120 && Math.abs(speed) < 0.30) rateLimit = 104;
    if (frontNear < 0.82) rateLimit = 46;
    var maxStep = rateLimit * dt;
    mem.refH = wrap(mem.refH + clamp(dref, -maxStep, maxStep));

