    }

    if (raw[3] < 0.62) avoid -= (0.62 - raw[3]) * 52;
    if (raw[4] < 0.62) avoid -= (0.62 - raw[4]) * 52;
    if (raw[0] < 0.62) avoid += (0.62 - raw[0]) * 52;
    if (raw[1] < 0.62) avoid += (0.62 - raw[1]) * 52;

    if (raw[0] < 0.34) avoid += (0.34 - raw[0]) * 55;
    if (raw[4] < 0.34) avoid -= (0.34 - raw[4]) * 55;

