    if (absE > 12) fwd *= Math.max(0.18, 1 - (absE - 12) / 78);
    if (absE > 85) fwd = Math.min(fwd, 0.13);
    if (Math.abs(turn) > 0.12) fwd *= 1 - (Math.abs(turn) - 0.12) * 1.7;
    if (dist < 2.05) fwd = Math.min(fwd, 0.28 + Math.max(0, dist - 0.72) * 0.20);
    if (dist < 0.85) fwd = Math.min(fwd, 0.22);

    var stopDist = 0.72 + Math.max(0, speed) * 0.56;
    if (frontSafe < stopDist) {
      var ratio = clamp((frontSafe - 0.38) / Math.max(0.15, stopDist - 0.38), 0, 1);
      fwd = Math.min(fwd, ratio * 0.72);
      if (frontSafe < 0.60) fwd = Math.min(fwd, 0.02);
      if (frontSafe < 0.46) fwd = Math.min(fwd, -0.06);
    }

    if (frontNear < 0.92) fwd = Math.min(fwd, 0.30);
    if (frontNear < 0.70) fwd = Math.min(fwd, 0.055);

