      var sideCap = 0.10 + Math.max(0, sideMin - 0.22) * 0.56;
      fwd = Math.min(fwd, sideCap);
    }
    if (sideMin < 0.50) fwd = Math.min(fwd, 0.055);
    if (sideMin < 0.36) fwd = Math.min(fwd, -0.045);
    if (sideMin < 0.26) fwd = Math.min(fwd, -0.10);

    if (frontSafe < 1.12) {
      var frontCap = 0.08 + Math.max(0, frontSafe - 0.38) * 0.58;
      fwd = Math.min(fwd, frontCap);
    }
    if (frontSafe < 0.68) fwd = Math.min(fwd, 0.10);
    if (frontSafe < 0.52) fwd = Math.min(fwd, -0.05);
    if (frontSafe < 0.40) fwd = Math.min(fwd, -0.13);

    if (farMin < 0.44 && nearAngleMin < 0.78) fwd = Math.min(fwd, 0.03);
    if (farMin < 0.31) fwd = Math.min(fwd, -0.05);

    if (mem.path && mem.path.length === 0 && dist > 1.5 &&
        now - (Number(mem.noPathSince) || now) > 1.2) {
