  function dead(u) {
    if (!isFinite(u)) return 0;
    u = clamp(u, -1, 1);
    if (Math.abs(u) < 0.025) return 0;
    if (Math.abs(u) < 0.075) return u > 0 ? 0.075 : -0.075;
