        right = -rev + rt;
      } else {
        var smEsc = Math.min(leftSafe, rightSafe);
        if (smEsc < 0.54 || escE < 0.88) {
          var pv = 0.13;
          left = -pv * eside;
          right = pv * eside;
        } else {
          var fEsc = 0.13;
          var tEsc = 0.052 * eside;
          left = fEsc - tEsc;
          right = fEsc + tEsc;
        }
      }

      if (escE > 0.62 && cenEsc > 0.95 && Math.min(leftSafe, rightSafe) > 0.66 && Math.abs(speed) < 0.25) {
        mem.escUntil = now - 0.001;
      }
      if (escE > 1.05 && escE < 2.25 &&
          (cenEsc < 0.52 || (farMin < 0.25 && sideMin < 0.38))) {
        if (now > (Number(mem.escUntil) || -999) - 0.20) {
          mem.escUntil = now + 0.30;
        }
      }
    }
  } else if (activeRec) {
    var er = now - (Number(mem.recStart) || now);
    var rside = Number(mem.recSide) || 1;

    if (er < 0.30) {
      left = -0.14;
      right = -0.14;
    } else if (er < 0.78) {
      if (frontSafe < 0.30) {
        left = -0.11;
        right = -0.11;
      } else {
        left = -0.13 * rside;
        right = 0.13 * rside;
      }
    } else {
      if (frontSafe > 0.58) {
        var fRec = 0.10;
        var tRec = 0.050 * rside;
        left = fRec - tRec;
        right = fRec + tRec;
      } else {
        left = -0.07;
        right = 0.12 * rside;
      }
    }
  } else {
    var planPeriod = (mem.path && mem.path.length > 1) ? 0.55 : 0.32;
    if (frontNear < 1.25 || sideMin < 0.70) planPeriod = Math.min(planPeriod, 0.40);
    if (speed > 1.20) planPeriod = Math.min(planPeriod, 0.42);
    var needPlan = targetChanged || !mem.path || mem.path.length === 0 ||
                   (now - (Number(mem.lastPlan) || -999) > planPeriod);

    if (dist > 0.65 && needPlan) {
      var p = computePath(3, 3, 36000);
      if (!p || p.length === 0) p = computePath(3, 2, 36000);
      if (!p || p.length === 0) p = computePath(2, 1, 36000);
      mem.path = p || [];
      mem.lastPlan = now;

      if (mem.path.length === 0) {
        if (!isFinite(mem.noPathSince) || mem.noPathSince < -100) mem.noPathSince = now;
      } else {
        mem.noPathSince = -999;
      }
    }

    if (dist < 0.55) mem.path = [];

    var desiredH = targetBearing;

    if (mem.path && mem.path.length > 1 && dist > 0.55) {
      var len = mem.path.length;
      var bestI = 0;
      var bestD = 1e18;

      for (var pi = 0; pi < len; pi++) {
        var pid = mem.path[pi];
        var pix = pid % GW;
        var piy = (pid - pix) / GW;
        var wx0 = pix * RES;
        var wy0 = piy * RES;
        var pdx = wx0 - px;
        var pdy = wy0 - py;
        var pd2 = pdx * pdx + pdy * pdy;
        if (pd2 < bestD) {
          bestD = pd2;
          bestI = pi;
        }
      }

      var look = 0.55 + Math.min(0.42, Math.max(0, speed) * 0.20);
      if (frontNear < 1.25 || sideMin < 0.68) look = 0.42;
      if (frontNear < 0.86) look = 0.34;
      if (look < 0.34) look = 0.34;

      var acc = 0;
      var lastPX = px;
      var lastPY = py;
      var idx = bestI;

      for (var pj = bestI; pj < len; pj++) {
        var pjd = mem.path[pj];
        var pjx = pjd % GW;
        var pjy = (pjd - pjx) / GW;
        var wxj = pjx * RES;
        var wyj = pjy * RES;
        var incx = wxj - lastPX;
        var incy = wyj - lastPY;
        var inc = Math.sqrt(incx * incx + incy * incy);
        acc += inc;
        lastPX = wxj;
        lastPY = wyj;
        idx = pj;
        if (acc >= look) break;
      }

      if (idx < bestI) idx = bestI;
      if (idx >= len) idx = len - 1;

      var wid = mem.path[idx];
      var wix = wid % GW;
      var wiy = (wid - wix) / GW;
      var wxp = wix * RES;
      var wyp = wiy * RES;

      if ((wxp - px) * (wxp - px) + (wyp - py) * (wyp - py) < 0.035 && idx < len - 1) {
        idx++;
        wid = mem.path[idx];
        wix = wid % GW;
        wiy = (wid - wix) / GW;
        wxp = wix * RES;
        wyp = wiy * RES;
      }

      desiredH = Math.atan2(wyp - py, wxp - px) * DEG;
      if (!isFinite(desiredH)) desiredH = targetBearing;
    }

    if (dist < 1.10) desiredH = targetBearing;

    var dref = wrap(desiredH - mem.refH);
    var rateLimit = 78;
    if (Math.abs(dref) > 120 && Math.abs(speed) < 0.32) rateLimit = 112;
    if (frontNear > 1.70 && sideMin > 0.82) rateLimit = 94;
    if (frontNear < 0.82) rateLimit = 48;
    var maxStep = rateLimit * dt;
    mem.refH = wrap(mem.refH + clamp(dref, -maxStep, maxStep));

    var errBase = wrap(mem.refH - trueH);

    var sideDecision = now > (Number(mem.avoidUntil) || -999) ||
                       targetChanged ||
                       Math.abs(errBase) > 70 ||
                       Math.abs(leftSafe - rightSafe) > 0.45 ||
                       sideMin < 0.52;
    if (sideDecision) {
      var ps = Number(mem.avoidSide) || 1;
      if (leftSafe > rightSafe + 0.11) ps = 1;
      else if (rightSafe > leftSafe + 0.11) ps = -1;
      else if (directErr > 12) ps = 1;
      else if (directErr < -12) ps = -1;
      if (!ps) ps = 1;

      mem.avoidSide = ps;
      mem.avoidUntil = now + (frontNear < 1.15 ? 0.30 : 0.58);
    }

    var avoidSide = Number(mem.avoidSide) || 1;
    var avoid = 0;

    if (frontNear < 1.35) {
      var str = (1.35 - frontNear) / 1.35;
      avoid += avoidSide * str * 38;
      if (raw[2] < 0.90) avoid += avoidSide * ((0.90 - raw[2]) / 0.90) * 20;
    }

    if (leftSafe < 0.98) avoid -= (0.98 - leftSafe) * 34;
    if (rightSafe < 0.98) avoid += (0.98 - rightSafe) * 34;

    if (leftC < 1.05) avoid -= (1.05 - leftC) * 13;
    if (rightC < 1.05) avoid += (1.05 - rightC) * 13;

    var smNow = Math.min(leftSafe, rightSafe);
    if (smNow < 1.38) {
      avoid += clamp((leftSafe - rightSafe) * 18, -22, 22);
    }

    if (raw[3] < 0.62) avoid -= (0.62 - raw[3]) * 52;
    if (raw[4] < 0.62) avoid -= (0.62 - raw[4]) * 52;
    if (raw[0] < 0.62) avoid += (0.62 - raw[0]) * 52;
    if (raw[1] < 0.62) avoid += (0.62 - raw[1]) * 52;

    if (raw[0] < 0.34) avoid += (0.34 - raw[0]) * 55;
    if (raw[4] < 0.34) avoid -= (0.34 - raw[4]) * 55;

    avoid = clamp(avoid, -66, 66);

    if (dist < 1.55) {
      var red = clamp((dist - 0.62) / 0.93, 0.35, 1.0);
      avoid *= red;
    }

    var oldAvoid = Number(mem.avoidF) || 0;
    mem.avoidF = oldAvoid + (avoid - oldAvoid) * Math.min(1, dt * 8);

    var errFinal = wrap(errBase + (Number(mem.avoidF) || 0));
    var absE = Math.abs(errFinal);
    var yaw = Number(mem.yawRate) || 0;

    var turnTarget = clamp(errFinal / 100 - yaw / 250, -0.205, 0.205);
    if (absE < 2.8 && Math.abs(yaw) < 12) turnTarget *= 0.42;

    var alphaT = Math.min(1, dt * 9);
    mem.turnF = (Number(mem.turnF) || 0) +
                (turnTarget - (Number(mem.turnF) || 0)) * alphaT;

    var turnCap = 0.21;
    if (frontNear < 1.02) turnCap = 0.170;
    if (sideMin < 0.62) turnCap = Math.min(turnCap, 0.145);
    if (frontSafe < 0.54) turnCap = Math.min(turnCap, 0.110);
    var turn = clamp(Number(mem.turnF) || 0, -turnCap, turnCap);

    var fwd = 0.60;
    if (frontNear > 2.10 && leftC > 1.25 && rightC > 1.25 &&
        absE < 15 && Math.abs(yaw) < 25) {
      fwd = 0.78;
    }
    if (frontNear > 2.80 && leftC > 1.60 && rightC > 1.60 &&
        absE < 10 && Math.abs(yaw) < 20) {
      fwd = 0.88;
    }

    if (absE > 12) fwd *= Math.max(0.20, 1 - (absE - 12) / 72);
    if (absE > 85) fwd = Math.min(fwd, 0.16);
    if (Math.abs(turn) > 0.12) fwd *= 1 - (Math.abs(turn) - 0.12) * 1.55;
    if (dist < 2.10) fwd = Math.min(fwd, 0.30 + Math.max(0, dist - 0.70) * 0.22);
    if (dist < 0.85) fwd = Math.min(fwd, 0.24);

    var stopDist = 0.78 + Math.max(0, speed) * 0.58;
    if (frontSafe < stopDist) {
      var ratio = clamp((frontSafe - 0.38) / Math.max(0.15, stopDist - 0.38), 0, 1);
      fwd = Math.min(fwd, ratio * 0.78);
      if (frontSafe < 0.58) fwd = Math.min(fwd, 0.03);
      if (frontSafe < 0.44) fwd = Math.min(fwd, -0.06);
    }

    if (frontNear < 0.90) fwd = Math.min(fwd, 0.32);
    if (frontNear < 0.68) fwd = Math.min(fwd, 0.06);

    if (sideMin < 0.90) {
      var sideCap = 0.13 + Math.max(0, sideMin - 0.20) * 0.62;
      fwd = Math.min(fwd, sideCap);
    }
    if (sideMin < 0.48) fwd = Math.min(fwd, 0.09);
    if (sideMin < 0.33) fwd = Math.min(fwd, -0.02);
    if (sideMin < 0.24) fwd = Math.min(fwd, -0.09);

    if (frontSafe < 1.05) {
      var frontCap = 0.09 + Math.max(0, frontSafe - 0.36) * 0.62;
      fwd = Math.min(fwd, frontCap);
    }
    if (frontSafe < 0.62) fwd = Math.min(fwd, 0.10);
    if (frontSafe < 0.48) fwd = Math.min(fwd, -0.03);
    if (frontSafe < 0.38) fwd = Math.min(fwd, -0.12);

    if (farMin < 0.40 && nearAngleMin < 0.72) fwd = Math.min(fwd, 0.05);
    if (farMin < 0.29) fwd = Math.min(fwd, -0.03);

    if (mem.path && mem.path.length === 0 && dist > 1.5 &&
        now - (Number(mem.noPathSince) || now) > 1.2) {
      fwd = Math.min(fwd, 0.45);
    }

    if (turn > 0 && leftSafe < 0.62) {
      turn *= clamp((leftSafe - 0.28) / 0.34, 0, 1);
    }
    if (turn < 0 && rightSafe < 0.62) {
      turn *= clamp((rightSafe - 0.28) / 0.34, 0, 1);
    }

    if (Math.abs(turn) < 0.006) turn = 0;
    fwd = clamp(fwd, -0.20, 1);

    left = fwd - turn;
    right = fwd + turn;
  }

  function dead(u) {
    if (!isFinite(u)) return 0;
    u = clamp(u, -1, 1);
    if (Math.abs(u) < 0.025) return 0;
    if (Math.abs(u) < 0.075) return u > 0 ? 0.075 : -0.075;
    return u;
  }

  left = dead(left);
  right = dead(right);

  var old = null;
  var bestAge = 1e9;
  for (var hi = 0; hi < mem.hist.length; hi++) {
    var age = now - mem.hist[hi].t;
    if (age >= 0.50 && age <= 1.05) {
      var score = Math.abs(age - 0.70);
      if (score < bestAge) {
        bestAge = score;
        old = mem.hist[hi];
      }
    }
  }

  if (old && speed > 0.36 && Math.abs(Number(mem.yawRate) || 0) < 28 &&
      frontSafe > 1.05 && leftSafe > 0.60 && rightSafe > 0.60) {
    var mdx = px - old.x;
    var mdy = py - old.y;
    var md = Math.sqrt(mdx * mdx + mdy * mdy);

    if (md > 0.20) {
      var motionH = Math.atan2(mdy, mdx) * DEG;
      var avgH = wrap(old.h + wrap(sensedH - old.h) * 0.5);
      var obsBias = wrap(avgH - motionH);
      var bDiff = wrap(obsBias - (Number(mem.bias) || 0));

      if (Math.abs(bDiff) < 70 && Math.abs(obsBias) < 70) {
        mem.bias = wrap((Number(mem.bias) || 0) + clamp(bDiff, -5, 5) * 0.018);
        if (mem.bias > 70) mem.bias = 70;
        if (mem.bias < -70) mem.bias = -70;
      }
    }
  }

  mem.hist.push({ t: now, x: px, y: py, h: sensedH });
  while (mem.hist.length && now - mem.hist[0].t > 2.3) mem.hist.shift();
  if (mem.hist.length > 140) mem.hist.shift();

  mem.prevCmdAvg = (left + right) * 0.5;

  return { left: left, right: right };
}
